  name,
  fallback,
  color = 'tiffany',
  muted = false,
}: {
  name?: string;
  fallback: string;
  color?: ComponentProps<typeof Avatar>['color'];
  muted?: boolean;
}) {
  return (
    <span
      className={cn(
