export function buildCandidateTree(
  rows: Candidate[],
  extraEmptyGroups: string[] = [],
): CandidateTreeRow[] {
  const groups = new Map<string, Candidate[]>();
  for (const row of rows) {
    const bucket = groups.get(row.jobTitle) ?? [];
    bucket.push(row);
    groups.set(row.jobTitle, bucket);
  }

  const populated: CandidateTreeRow[] = Array.from(
    groups,
    ([title, leaves]) => ({
      id: `group-${title}`,
      kind: 'group',
      title,
      subRows: leaves.map((leaf) => ({
        ...leaf,
        kind: 'candidate' as const,
      })),
    }),
  );

  const empty: CandidateTreeRow[] = extraEmptyGroups.map((title) => ({
    id: `group-${title}`,
    kind: 'group',
    title,
    subRows: [],
  }));

  return [...populated, ...empty];
}

import type { Column, Table } from '@tanstack/react-table';
import type { CSSProperties } from 'react';

/**
 * Column ids may contain characters that are not valid in a CSS custom
 * property name, so they are slugified before being used as a variable.
 */
function slug(columnId: string) {
  return columnId.replace(/[^\w-]/g, '-');
}

export function columnSizeVar(columnId: string) {
  return `--col-${slug(columnId)}-size`;
}

function columnStartVar(columnId: string) {
  return `--col-${slug(columnId)}-start`;
}

function columnEndVar(columnId: string) {
  return `--col-${slug(columnId)}-end`;
}

/** Same order as `getHeaderGroups()`: left pins, unpinned, right pins. */
export function getLeafColumnsInDisplayOrder<TData>(
  table: Table<TData>,
) {
  return [
    ...table.getLeftVisibleLeafColumns(),
    ...table.getCenterVisibleLeafColumns(),
    ...table.getRightVisibleLeafColumns(),
  ];
}

/**
 * Widths and pinned offsets as CSS variables, set once on `<table>`.
 *
 * Column resizing then only rewrites that one `style` attribute: the colgroup
 * widths and every pinned `left` / `right` offset read from these variables, so
 * the rows do not have to re-render mid-drag. Pinned offsets have to be
 * included because widening a pinned column pushes the others along it.
 */
export function getColumnSizeVars<TData>(
  table: Table<TData>,
): CSSProperties {
  const vars: Record<string, string> = {
    '--table-total-size': `${table.getTotalSize()}px`,
  };

  for (const column of table.getVisibleLeafColumns()) {
    vars[columnSizeVar(column.id)] = `${column.getSize()}px`;
    vars[columnStartVar(column.id)] = `${column.getStart('left')}px`;
    vars[columnEndVar(column.id)] = `${column.getAfter('right')}px`;
  }

  return vars as CSSProperties;
}

/**
 * Width for the trailing filler column.
 *
 * Under `table-fixed` a percentage column is clamped to the space the sized
 * columns leave over, so `100%` means "take the slack, or nothing": it is 0 when
 * the columns already fill the frame and exactly the leftover when they don't.
 * The sized columns therefore always render at the width they were dragged to.
 *
 * `auto` does NOT work here — Chrome hands an unsized column an equal share of
 * the table width (and widens the table to fit it) instead of the leftover.
 */
export const FILLER_COLUMN_WIDTH = '100%';

export function getCommonPinningStyles<TData>(
  column: Column<TData>,
  zIndex = 1,
  // When set, the cell also sticks vertically at this top offset (px).
  // Needed for header rows: pinned columns already use `position: sticky`
  // (horizontal), but unpinned columns default to `relative`, so a plain
  // CSS class can't make the whole header row stick under border-separate.
  stickyTop?: number,
): CSSProperties {
  const isPinned = column.getIsPinned();
  const isLastLeftPinnedColumn =
    isPinned === 'left' && column.getIsLastColumn('left');
  const isFirstRightPinnedColumn =
    isPinned === 'right' && column.getIsFirstColumn('right');
  const isSticky = Boolean(isPinned) || stickyTop !== undefined;
  // In a sticky header row, pinned columns sit at the top-left corner and must
  // stay above the unpinned headers when scrolling horizontally (unpinned cells
  // come later in the DOM, so equal z-index would let them paint on top).
  const zIndexValue = !isSticky
    ? 0
    : isPinned && stickyTop !== undefined
      ? zIndex + 10
      : zIndex;

  return {
    boxShadow: isLastLeftPinnedColumn
      ? 'inset -1px 0 0 var(--grayscale-opacity-300)'
      : isFirstRightPinnedColumn
        ? 'inset 1px 0 0 var(--grayscale-opacity-300)'
        : undefined,
    left:
      isPinned === 'left'
        ? `var(${columnStartVar(column.id)})`
        : undefined,
    right:
      isPinned === 'right'
        ? `var(${columnEndVar(column.id)})`
        : undefined,
    top: stickyTop,
    opacity: 1,
    position: isSticky ? 'sticky' : 'relative',
    // Widths come from the colgroup; a pinned cell still needs its own width so
    // the sticky box matches the column while the rest scrolls under it.
    width: `var(${columnSizeVar(column.id)})`,
    zIndex: zIndexValue,
  };
}

export function getPinnedCellClassName<TData>(
  column: Column<TData>,
  className: string,
) {
  return [
    className,
    // Pinned cells keep their inline z-index (body = 20, header = 40) so they
    // stay below the sticky header (unpinned 30 / pinned 40). The hover/select
    // states only swap the background — they must NOT raise z-index, or a
    // hovered/selected frozen body cell would paint over the sticky header
    // while scrolling vertically.
    column.getIsPinned() &&
      'bg-white group-hover:bg-[#f8f8f9] group-data-[state=selected]:bg-[#f8f8f9]',
  ]
    .filter(Boolean)
    .join(' ');
}

import { cn } from '@/lib/utils';
import type { Header } from '@tanstack/react-table';
import type { MouseEvent, TouchEvent } from 'react';

const NUDGE_STEP = 8;
const NUDGE_STEP_LARGE = 40;
const RAISED_Z = '60';
const TOUCH_MOVE_OPTS: AddEventListenerOptions = {
  capture: true,
  passive: false,
};
const TOUCH_END_OPTS: AddEventListenerOptions = { capture: true };

type Ghost = {
  startX: number;
  size: number;
  minSize: number;
  maxSize: number;
};

function pointerClientX(
  event: globalThis.MouseEvent | globalThis.TouchEvent,
) {
  if ('touches' in event) {
    // `touchend` has an empty `touches` list; the lifted finger is only in
    // `changedTouches`. TanStack's `onEnd(e.touches[0]?.clientX)` hits this.
    return (
      event.touches[0]?.clientX ?? event.changedTouches[0]?.clientX
    );
  }
  return event.clientX;
}

function clampedGhostWidth(ghost: Ghost, clientX: number) {
  return Math.min(
    Math.max(ghost.size + clientX - ghost.startX, ghost.minSize),
    ghost.maxSize,
  );
}

/**
 * The drag guide runs from the header down through the body, so its height
 * cannot come from the `th` it lives in. Measure the scroll container once per
 * drag and hand the value to CSS.
 *
 * Measuring (instead of using a huge value) keeps the guide from adding
 * scrollable overflow, and keeping it inside the `th` means a pinned column's
 * guide inherits that cell's sticky offset for free.
 *
 * A layout can repeat the header row per group (see `data-table-group-02`), and
 * those later rows are sticky with a z-index, so a single segment drawn from
 * the grabbed handle gets painted over and the line comes out broken. Every
 * copy of the column therefore draws its own segment from its own row down to
 * the end of the content; overlapped, they read as one continuous line.
 *
 * In `onEnd` mode the guide has to track the pointer, and it does so
 * imperatively: a layout may memoize its rows and freeze them for the drag
 * (`data-table-group-01` / `-02` do), which would freeze a React-driven ghost
 * offset along with them and leave the drag with no feedback at all.
 */
function startResizeGuide(
  handle: HTMLElement,
  ghost: Ghost | null,
  onCommit?: (width: number) => void,
) {
  const container = handle.closest<HTMLElement>(
    '[data-slot="table-container"]',
  );
  if (!container) return;

  const { columnId } = handle.dataset;
  const containerTop = container.getBoundingClientRect().top;
  const guides = Array.from(
    container.querySelectorAll<HTMLElement>(
      '[data-slot="data-table-resize-handle"]',
    ),
  ).filter((guide) => guide.dataset.columnId === columnId);

  // Sticky group-title rows sit above the header rows and would clip the
  // segments, so the cells hosting a guide are lifted for the drag and put back
  // afterwards. `RAISED_Z` clears the highest layer these layouts use (the
  // group title at z-50 in `data-table-group-01`).
  const raised: { el: HTMLElement; zIndex: string }[] = [];
  const raise = (el: Element | null) => {
    if (!(el instanceof HTMLElement)) return;
    raised.push({ el, zIndex: el.style.zIndex });
    el.style.zIndex = RAISED_Z;
  };

  for (const guide of guides) {
    const top =
      guide.getBoundingClientRect().top -
      containerTop +
      container.scrollTop;
    guide.style.setProperty(
      '--table-resize-guide-height',
      `${container.scrollHeight - top}px`,
    );
    guide.dataset.guide = 'true';
    raise(guide.closest('th, td'));
    raise(guide.closest('tr'));
  }

  const track = (
    event: globalThis.MouseEvent | globalThis.TouchEvent,
  ) => {
    if (!ghost) return;
    const clientX = pointerClientX(event);
    if (clientX === undefined) return;
    const next = clampedGhostWidth(ghost, clientX);
    for (const guide of guides) {
      guide.style.transform = `translateX(${next - ghost.size}px)`;
    }
  };

  const clear = () => {
    for (const guide of guides) {
      delete guide.dataset.guide;
      guide.style.removeProperty('--table-resize-guide-height');
      guide.style.removeProperty('transform');
    }
    for (const { el, zIndex } of raised) {
      el.style.zIndex = zIndex;
    }
    window.removeEventListener('mousemove', track);
    window.removeEventListener('mouseup', clear);
    window.removeEventListener('touchmove', track, TOUCH_MOVE_OPTS);
    window.removeEventListener(
      'touchend',
      onTouchEnd,
      TOUCH_END_OPTS,
    );
  };

  const onTouchEnd = (event: globalThis.TouchEvent) => {
    const clientX = pointerClientX(event);
    if (ghost && onCommit && clientX !== undefined) {
      onCommit(clampedGhostWidth(ghost, clientX));
    }
    clear();
  };

  if (ghost) {
    window.addEventListener('mousemove', track);
    // TanStack stopPropagates touchmove/touchend on `document`, so window
    // bubble never runs; capture on window sees the event first.
    window.addEventListener('touchmove', track, TOUCH_MOVE_OPTS);
  }
  window.addEventListener('mouseup', clear);
  window.addEventListener('touchend', onTouchEnd, TOUCH_END_OPTS);
}

export interface ResizeHandleProps<TData, TValue> {
  header: Header<TData, TValue>;
  /** Accessible name. Defaults to the column id. */
  label?: string;
  className?: string;
}

/**
 * Drag target that sits on the right edge of a `TableHead`.
 *
 * - pointer / touch drag resizes the column
 * - double click or `Home` resets it to the column's `size`
 * - `ArrowLeft` / `ArrowRight` nudge by 8px (40px with `Shift`)
 *
 * With `columnResizeMode: 'onEnd'` the guide follows the pointer and the column
 * only commits on release.
 */
export function ResizeHandle<TData, TValue>({
  header,
  label,
  className,
}: ResizeHandleProps<TData, TValue>) {
  const { column } = header;
  const { table } = header.getContext();

  if (!column.getCanResize()) {
    return null;
  }

  const isResizing = column.getIsResizing();
  const minSize =
    column.columnDef.minSize ??
    table.options.defaultColumn?.minSize ??
    20;
  const maxSize =
    column.columnDef.maxSize ?? table.options.defaultColumn?.maxSize;

  const resize = (delta: number) => {
    const next = Math.min(
      Math.max(column.getSize() + delta, minSize),
      maxSize ?? Number.MAX_SAFE_INTEGER,
    );
    table.setColumnSizing((sizing) => ({
      ...sizing,
      [column.id]: next,
    }));
  };

  const startDrag = (
    event: MouseEvent<HTMLDivElement> | TouchEvent<HTMLDivElement>,
  ) => {
    // Without this the drag selects the header text it passes over.
    if (event.type === 'mousedown') event.preventDefault();
    const startX =
      'touches' in event ? event.touches[0]?.clientX : event.clientX;
    // In `onEnd` mode the column stays put during the drag, so the guide
    // itself moves to show where the edge will land.
    const ghost =
      table.options.columnResizeMode === 'onEnd' &&
      startX !== undefined
        ? {
            startX,
            size: column.getSize(),
            minSize,
            maxSize: maxSize ?? Number.MAX_SAFE_INTEGER,
          }
        : null;
    startResizeGuide(event.currentTarget, ghost, (width) => {
      table.setColumnSizing((sizing) => ({
        ...sizing,
        [column.id]: width,
      }));
    });
    header.getResizeHandler()(event);
  };

  return (
    <div
      role="separator"
      aria-orientation="vertical"
      aria-label={label ?? `Resize ${column.id} column`}
      aria-valuenow={column.getSize()}
      aria-valuemin={minSize}
      aria-valuemax={maxSize}
      tabIndex={0}
      data-slot="data-table-resize-handle"
      data-column-id={column.id}
      data-resizing={isResizing || undefined}
      onMouseDown={startDrag}
      onTouchStart={startDrag}
      onClick={(event) => event.stopPropagation()}
      onDoubleClick={(event) => {
        event.stopPropagation();
        column.resetSize();
      }}
      onKeyDown={(event) => {
        if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
          event.preventDefault();
          const step = event.shiftKey ? NUDGE_STEP_LARGE : NUDGE_STEP;
          resize(event.key === 'ArrowLeft' ? -step : step);
          return;
        }
        if (event.key === 'Home') {
          event.preventDefault();
          column.resetSize();
        }
      }}
      className={cn(
        'absolute inset-y-0 right-0 z-30 w-2 cursor-col-resize touch-none select-none',
        'after:absolute after:top-0 after:right-0 after:h-full after:w-px after:bg-transparent after:content-[""]',
        // Hover shows nothing but the col-resize cursor; the only blue line is
        // the drag guide.
        'focus-visible:outline-none focus-visible:after:w-0.5 focus-visible:after:bg-primary-500',
        // While dragging, the grabbed handle becomes a guide line that runs
        // down the whole body.
        'data-[guide]:after:h-[var(--table-resize-guide-height,100%)] data-[guide]:after:w-0.5 data-[guide]:after:bg-primary-500',
        className,
      )}
    />
  );
}
